from collections.abc import Mapping


def _check_specs(field_specs):
    if not isinstance(field_specs, list):
        raise ValueError("field_specs must be a list")
    seen = set()
    allowed = {"name", "kind", "required"}
    for spec in field_specs:
        if not isinstance(spec, dict) or set(spec) - allowed:
            raise ValueError("invalid field specification")
        name = spec.get("name")
        kind = spec.get("kind")
        required = spec.get("required", False)
        if not isinstance(name, str) or not name or name in seen:
            raise ValueError("invalid or duplicate field name")
        if kind not in {"text", "integer", "labels"}:
            raise ValueError("invalid field kind")
        if not isinstance(required, bool):
            raise ValueError("required must be Boolean")
        seen.add(name)
    return seen


def compile_record(field_specs, raw_values):
    names = _check_specs(field_specs)
    if not isinstance(raw_values, Mapping):
        raise TypeError("raw_values must be a mapping")

    record = {}
    errors = {}
    for spec in field_specs:
        name = spec["name"]
        required = spec.get("required", False)
        if name not in raw_values:
            if required:
                errors[name] = "required"
            continue

        value = raw_values[name]
        kind = spec["kind"]
        if kind == "text":
            if not isinstance(value, str):
                errors[name] = "invalid type"
                continue
            value = value.strip()
            if required and not value:
                errors[name] = "required"
                continue
            record[name] = value
        elif kind == "integer":
            if not isinstance(value, int) or isinstance(value, bool):
                errors[name] = "invalid type"
                continue
            record[name] = value
        else:
            if not isinstance(value, list) or any(not isinstance(x, str) for x in value):
                errors[name] = "invalid type"
                continue
            record[name] = value

    extra = sorted(key for key in raw_values if key not in names)
    if extra:
        errors["__extra__"] = extra
    return record, errors

